<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';

interface Props { userName?: string; userEmail?: string }
interface Supplier { id:number; supplier_code:string; name:string; legal_name?:string|null; email:string|null; phone:string|null; tax_number?:string|null; status:string; credit_days:number; contact_person?:string|null; address?:string|null; city?:string|null; country?:string|null; payment_terms?:string|null; notes?:string|null; purchase_orders_count?:number }
interface SupplierContact { id:number; name:string; designation:string|null; email:string|null; phone:string|null; is_primary:boolean; notes:string|null }
interface SupplierDocument { id:number; category:string; original_name:string; mime_type:string; size:number; expires_at:string|null; created_at:string|null }
interface SupplierProfile extends Supplier { contacts:SupplierContact[]; documents:SupplierDocument[]; invoices_count:number; purchase_orders_count:number; purchase_orders:{id:number;po_number:string;order_date:string|null;status:string;grand_total:string;location:string|null;revision_no?:number|null}[]; activity:{id:number;action:string;description:string;created_at:string}[] }
interface Location { id:number; name:string; access_level:string }
interface Product { id:number; name:string; sku:string|null }
interface Variant { id:number; product_id:number; name:string; sku:string; product?:{name:string} }
interface POItem { id:number; product_id:number|null; product_variant_id:number|null; description:string|null; quantity:string; received_quantity:string; accepted_quantity:string; unit_cost:string; discount_amount:string; tax_amount:string; line_total:string; product?:Product|null; variant?:Variant|null }
interface PurchaseOrderRevision { id:number; revision_number:number; status:string; reason:string; proposed_data:{ order_date?:string; expected_at?:string|null; notes?:string|null; items?:RevisionItem[] }; rejection_reason?:string|null; submitted_at:string; reviewed_at?:string|null; creator?:{id:number;name:string}; reviewer?:{id:number;name:string} }
interface RevisionItem { product_id:number|null; product_variant_id:number|null; description:string|null; quantity:string; unit_cost:string; discount_amount:string; tax_amount:string }
interface PurchaseOrder { id:number; po_number:string; supplier_id:number; location_id:number; status:string; grand_total:string; order_date?:string; expected_at?:string|null; currency?:string; notes?:string|null; revision_no?:number; supplier?:Supplier; location?:Location; items:POItem[]; revisions?:PurchaseOrderRevision[] }
interface RequisitionItem { id:number; product_id:number|null; product_variant_id:number|null; quantity:string; product?:Product|null; variant?:Variant|null }
interface Requisition { id:number; requisition_number:string; status:string; purpose:string|null; required_by?:string|null; location_id:number; location?:Location; items:RequisitionItem[] }
interface Invoice { id:number; invoice_number:string; supplier_id:number; purchase_order_id:number; status:string; grand_total:string; paid_total:string; supplier?:Supplier; purchase_order?:PurchaseOrder; items?:{purchase_order_item_id:number;quantity:string;unit_cost:string;line_total:string}[] }
interface Receipt { id:number; grn_number:string; status:string; received_date:string }
interface Payment { id:number; payment_number:string; amount:string; payment_date:string; supplier_invoice?:Invoice }
interface SupplierReturn { id:number; supplier_invoice_id:number; return_number:string; total_amount:string; return_date:string; items?:{purchase_order_item_id:number;quantity:string}[] }
interface Overview {
    suppliers:Supplier[]; requisitions:Requisition[]; purchase_orders:PurchaseOrder[];
    goods_receipts:Receipt[]; invoices:Invoice[]; payments:Payment[]; returns:SupplierReturn[];
    locations:Location[]; products:Product[]; variants:Variant[]; cash_accounts:{id:number;code:string;name:string}[]; supplier_balances:{supplier_id:number;balance:string}[]; summary:{active_suppliers:number;open_purchase_orders:number;unpaid_invoices:number;outstanding_payable:string};
}
const props = withDefaults(defineProps<Props>(), { userName:'', userEmail:'' });
const loading = ref(false), saving = ref(false), error = ref(''), success = ref('');
const tab = ref<'suppliers'|'requisitions'|'orders'|'receipts'|'invoices'|'payments'|'returns'>('suppliers');
const data = ref<Overview|null>(null);
const editingSupplierId = ref<number|null>(null);
const profileSupplier = ref<SupplierProfile|null>(null), profileLoading = ref(false), profileSaving = ref(false);
const contactForm = reactive({ name:'', designation:'', email:'', phone:'', is_primary:false, notes:'' });
const documentCategory = ref('other'), documentExpiry = ref('');
const showSupplier = ref(false), showOrder = ref(false), showReceive = ref(false), showInvoice = ref(false), showPayment = ref(false), showReturn = ref(false), showRequisition = ref(false), showRevision = ref(false);
const supplierForm = reactive({ supplier_code:'', name:'', legal_name:'', email:'', phone:'', tax_number:'', contact_person:'', address:'', city:'', country:'Bangladesh', payment_terms:'', credit_days:'0', status:'active', notes:'' });
const requisitionForm = reactive({ location_id:'', purpose:'', required_by:'' });
const requisitionItems = ref<Array<{product_id:number|null;product_variant_id:number|null;quantity:string}>>([{product_id:null,product_variant_id:null,quantity:'1'}]);
const orderForm = reactive({ supplier_id:'', location_id:'', purchase_requisition_id:'', order_date:new Date().toISOString().slice(0,10), expected_at:'', notes:'' });
const orderItems = ref<Array<{product_id:number|null;product_variant_id:number|null;quantity:string;unit_cost:string;discount_amount:string;tax_amount:string;description:string}>>([{product_id:null,product_variant_id:null,quantity:'1',unit_cost:'0.00',discount_amount:'0.00',tax_amount:'0.00',description:''}]);
const receiveForm = reactive({ order_id:'', received_date:new Date().toISOString().slice(0,10), delivery_note:'', purchase_order_item_id:'', received_quantity:'1', accepted_quantity:'1', rejected_quantity:'0', rejection_reason:'' });
const invoiceForm = reactive({ order_id:'', invoice_number:'', invoice_date:new Date().toISOString().slice(0,10), due_date:'', purchase_order_item_id:'', quantity:'1', unit_cost:'0.00', tax_total:'0.00', discount_total:'0.00' });
const paymentForm = reactive({ invoice_id:'', payment_date:new Date().toISOString().slice(0,10), amount:'', payment_method:'bank', cash_account_id:'', reference:'' });
const returnForm = reactive({ invoice_id:'', reason:'', purchase_order_item_id:'', quantity:'1', return_date:new Date().toISOString().slice(0,10) });
const revisionOrder = ref<PurchaseOrder|null>(null);
const revisionForm = reactive({ reason:'', order_date:'', expected_at:'', notes:'' });
const revisionItems = ref<RevisionItem[]>([]);

const selectedOrder = computed(() => data.value?.purchase_orders.find(x => String(x.id)===receiveForm.order_id) ?? null);
const selectedReturnInvoice = computed(() => data.value?.invoices.find(x => String(x.id)===returnForm.invoice_id) ?? null);
const selectedReturnOrder = computed(() => data.value?.purchase_orders.find(x => x.id===selectedReturnInvoice.value?.purchase_order_id) ?? null);
const csrf = () => decodeURIComponent(document.cookie.split('; ').find(v => v.startsWith('XSRF-TOKEN='))?.split('=')[1] ?? '');
async function api<T>(url:string, options:RequestInit={}):Promise<T> {
    const response = await fetch(url,{credentials:'same-origin',...options,headers:{Accept:'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest','X-XSRF-TOKEN':csrf(),...(options.headers??{})}});
    const payload = await response.json().catch(()=>({}));
    if(!response.ok){ const message=payload.errors?Object.values(payload.errors).flat().join(' '):payload.message; throw new Error(message||'Request failed.'); }
    return payload as T;
}
async function load():Promise<void> {
    loading.value=true; error.value='';
    try { data.value=await api<Overview>('/api/v1/backend/procurement/overview'); }
    catch(e){ error.value=e instanceof Error?e.message:'Unable to load procurement data.'; }
    finally { loading.value=false; }
}
async function submit(url:string, body:unknown, close:()=>void, message:string, method:'POST'|'PUT'='POST'):Promise<void> {
    saving.value=true; error.value=''; success.value='';
    try { await api(url,{method,body:JSON.stringify(body)}); close(); success.value=message; await load(); }
    catch(e){ error.value=e instanceof Error?e.message:'Unable to save procurement record.'; }
    finally { saving.value=false; }
}
function openSupplier():void { editingSupplierId.value=null; Object.assign(supplierForm,{supplier_code:'',name:'',legal_name:'',email:'',phone:'',tax_number:'',contact_person:'',address:'',city:'',country:'Bangladesh',payment_terms:'',credit_days:'0',status:'active',notes:''}); showSupplier.value=true; }
function editSupplier(supplier:Supplier):void { editingSupplierId.value=supplier.id; Object.assign(supplierForm,{supplier_code:supplier.supplier_code,name:supplier.name,legal_name:supplier.legal_name??'',email:supplier.email??'',phone:supplier.phone??'',tax_number:supplier.tax_number??'',contact_person:supplier.contact_person??'',address:supplier.address??'',city:supplier.city??'',country:supplier.country??'Bangladesh',payment_terms:supplier.payment_terms??'',credit_days:String(supplier.credit_days??0),status:supplier.status,notes:supplier.notes??''}); showSupplier.value=true; }
function saveSupplier():void { const body={...supplierForm,credit_days:Number(supplierForm.credit_days)}; void submit(editingSupplierId.value?`/api/v1/backend/procurement/suppliers/${editingSupplierId.value}`:'/api/v1/backend/procurement/suppliers',body,()=>showSupplier.value=false,editingSupplierId.value?'Supplier updated.':'Supplier created.',editingSupplierId.value?'PUT':'POST'); }
function addRequisitionItem():void { requisitionItems.value.push({product_id:null,product_variant_id:null,quantity:'1'}); }
function removeRequisitionItem(index:number):void { if(requisitionItems.value.length>1) requisitionItems.value.splice(index,1); }
function saveRequisition():void {
    if(!requisitionForm.location_id || requisitionItems.value.some(item => (!item.product_id && !item.product_variant_id) || Number(item.quantity)<=0)) { error.value='Select a location and a valid product/variant and quantity for every line.'; return; }
    void submit('/api/v1/backend/procurement/requisitions',{location_id:Number(requisitionForm.location_id),purpose:requisitionForm.purpose,required_by:requisitionForm.required_by||null,items:requisitionItems.value.map(item=>({...item}))},()=>showRequisition.value=false,'Purchase requisition created.');
}
function addOrderItem():void { orderItems.value.push({product_id:null,product_variant_id:null,quantity:'1',unit_cost:'0.00',discount_amount:'0.00',tax_amount:'0.00',description:''}); }
function removeOrderItem(index:number):void { if(orderItems.value.length>1) orderItems.value.splice(index,1); }
function loadRequisitionLines():void {
    const req=data.value?.requisitions.find(item=>String(item.id)===orderForm.purchase_requisition_id);
    if(!req) return;
    orderForm.location_id=String(req.location_id);
    orderItems.value=req.items.map(item=>({product_id:item.product_id,product_variant_id:item.product_variant_id,quantity:item.quantity,unit_cost:'0.00',discount_amount:'0.00',tax_amount:'0.00',description:''}));
}
function saveOrder():void {
    if(!orderForm.supplier_id||!orderForm.location_id||orderItems.value.some(item=>(!item.product_id&&!item.product_variant_id)||Number(item.quantity)<=0||Number(item.unit_cost)<=0||Number(item.discount_amount)<0||Number(item.tax_amount)<0)){error.value='Select supplier, location and valid product, quantity, unit cost, discount and tax for every line.';return;}
    void submit('/api/v1/backend/procurement/orders',{supplier_id:Number(orderForm.supplier_id),location_id:Number(orderForm.location_id),purchase_requisition_id:orderForm.purchase_requisition_id?Number(orderForm.purchase_requisition_id):null,order_date:orderForm.order_date,expected_at:orderForm.expected_at||null,notes:orderForm.notes,items:orderItems.value.map(item=>({...item}))},()=>showOrder.value=false,'Purchase order created as draft.');
}
function openReceive(po:PurchaseOrder):void { receiveForm.order_id=String(po.id); receiveForm.purchase_order_item_id=''; receiveForm.received_quantity='1'; receiveForm.accepted_quantity='1'; receiveForm.rejected_quantity='0'; showReceive.value=true; }
function saveReceipt():void {
    const po=selectedOrder.value; if(!po||!receiveForm.purchase_order_item_id){error.value='Select a purchase order item.';return;}
    void submit(`/api/v1/backend/procurement/orders/${po.id}/receive`,{received_date:receiveForm.received_date,delivery_note:receiveForm.delivery_note,idempotency_key:crypto.randomUUID(),items:[{purchase_order_item_id:Number(receiveForm.purchase_order_item_id),received_quantity:receiveForm.received_quantity,accepted_quantity:receiveForm.accepted_quantity,rejected_quantity:receiveForm.rejected_quantity,rejection_reason:receiveForm.rejection_reason||null}]},()=>showReceive.value=false,'Goods receipt posted and accepted stock received.');
}
function invoiceRemaining(po:PurchaseOrder,item:POItem):number {
    const billed=(data.value?.invoices??[]).filter(x=>x.purchase_order_id===po.id).flatMap(x=>x.items??[]).filter(x=>x.purchase_order_item_id===item.id).reduce((sum,x)=>sum+Number(x.quantity),0);
    return Math.max(0,Number(item.accepted_quantity)-billed);
}
function openInvoice(po:PurchaseOrder):void {
    const item=po.items.find(x=>invoiceRemaining(po,x)>0);
    const qty=item?invoiceRemaining(po,item):0, ordered=Number(item?.quantity??0);
    const ratio=ordered>0?qty/ordered:0;
    invoiceForm.order_id=String(po.id); invoiceForm.invoice_number=''; invoiceForm.purchase_order_item_id=String(item?.id??'');
    invoiceForm.quantity=qty>0?qty.toString():'1'; invoiceForm.unit_cost=item?.unit_cost??'0.00';
    invoiceForm.tax_total=(Number(item?.tax_amount??0)*ratio).toFixed(2);
    invoiceForm.discount_total=(Number(item?.discount_amount??0)*ratio).toFixed(2);
    showInvoice.value=true;
}
function saveInvoice():void { void submit(`/api/v1/backend/procurement/orders/${invoiceForm.order_id}/invoices`,{invoice_number:invoiceForm.invoice_number,invoice_date:invoiceForm.invoice_date,due_date:invoiceForm.due_date||null,items:[{purchase_order_item_id:Number(invoiceForm.purchase_order_item_id),quantity:invoiceForm.quantity,unit_cost:invoiceForm.unit_cost}],tax_total:invoiceForm.tax_total,discount_total:invoiceForm.discount_total},()=>showInvoice.value=false,'Supplier invoice saved as draft.'); }
function postInvoice(invoice:Invoice):void { void submit(`/api/v1/backend/procurement/invoices/${invoice.id}/post`,{},()=>{},'Supplier invoice posted to Accounts Payable.'); }
function openPayment(invoice:Invoice):void { paymentForm.invoice_id=String(invoice.id); paymentForm.amount=(Number(invoice.grand_total)-Number(invoice.paid_total)).toFixed(2); paymentForm.cash_account_id=String(data.value?.cash_accounts[0]?.id??''); showPayment.value=true; }
function returnRemaining(invoice:Invoice,itemId:number):number {
    const billed=Number(invoice.items?.find(x=>x.purchase_order_item_id===itemId)?.quantity??0);
    const returned=(data.value?.returns??[]).filter(x=>x.supplier_invoice_id===invoice.id).flatMap(x=>x.items??[]).filter(x=>x.purchase_order_item_id===itemId).reduce((sum,x)=>sum+Number(x.quantity),0);
    return Math.max(0,billed-returned);
}
function openReturn(invoice:Invoice):void {
    const item=invoice.items?.find(x=>returnRemaining(invoice,x.purchase_order_item_id)>0);
    returnForm.invoice_id=String(invoice.id); returnForm.reason=''; returnForm.purchase_order_item_id=String(item?.purchase_order_item_id??''); returnForm.quantity=item?String(returnRemaining(invoice,item.purchase_order_item_id)):'1'; showReturn.value=true;
}
function saveReturn():void { if(!returnForm.purchase_order_item_id){error.value='Select a purchase order item.';return;} void submit(`/api/v1/backend/procurement/invoices/${returnForm.invoice_id}/returns`,{return_date:returnForm.return_date,reason:returnForm.reason,idempotency_key:crypto.randomUUID(),items:[{purchase_order_item_id:Number(returnForm.purchase_order_item_id),quantity:returnForm.quantity}]},()=>showReturn.value=false,'Supplier return posted and inventory/accounting adjusted.'); }
function savePayment():void { void submit(`/api/v1/backend/procurement/invoices/${paymentForm.invoice_id}/payments`,{payment_date:paymentForm.payment_date,amount:paymentForm.amount,payment_method:paymentForm.payment_method,cash_account_id:Number(paymentForm.cash_account_id),reference:paymentForm.reference||null,idempotency_key:crypto.randomUUID()},()=>showPayment.value=false,'Supplier payment posted.'); }
function openRevision(po:PurchaseOrder):void {
    revisionOrder.value=po;
    Object.assign(revisionForm,{reason:'',order_date:po.order_date??new Date().toISOString().slice(0,10),expected_at:po.expected_at??'',notes:po.notes??''});
    revisionItems.value=po.items.map(item=>({
        product_id:item.product_id,
        product_variant_id:item.product_variant_id,
        description:item.description??null,
        quantity:item.quantity,
        unit_cost:item.unit_cost,
        discount_amount:item.discount_amount,
        tax_amount:item.tax_amount,
    }));
    showRevision.value=true;
}
function addRevisionItem():void {
    revisionItems.value.push({product_id:null,product_variant_id:null,description:'',quantity:'1',unit_cost:'0.00',discount_amount:'0.00',tax_amount:'0.00'});
}
function removeRevisionItem(index:number):void {
    if(revisionItems.value.length>1) revisionItems.value.splice(index,1);
}
function saveRevision():void {
    const po=revisionOrder.value;
    if(!po||revisionItems.value.length===0){error.value='A revision must contain at least one item.';return;}
    if(revisionItems.value.some(item=>!item.product_id&&!item.product_variant_id)){error.value='Each revision line must select a product or variant.';return;}
    void submit(`/api/v1/backend/procurement/orders/${po.id}/revisions`,{
        reason:revisionForm.reason,order_date:revisionForm.order_date,expected_at:revisionForm.expected_at||null,notes:revisionForm.notes||null,
        items:revisionItems.value,
    },()=>{showRevision.value=false;revisionOrder.value=null;},'Purchase order revision submitted for independent approval.');
}
function approveRevision(revision:PurchaseOrderRevision):void {
    void submit(`/api/v1/backend/procurement/order-revisions/${revision.id}/approve`,{},()=>{},`Revision #${revision.revision_number} approved and applied.`);
}
function rejectRevision(revision:PurchaseOrderRevision):void {
    const reason=window.prompt('Enter revision rejection reason:');
    if(reason?.trim()) void submit(`/api/v1/backend/procurement/order-revisions/${revision.id}/reject`,{reason:reason.trim()},()=>{},`Revision #${revision.revision_number} rejected.`);
}

function submitRequisition(row:Requisition):void { void submit(`/api/v1/backend/procurement/requisitions/${row.id}/submit`,{},()=>{},'Requisition submitted for approval.'); }
function approveRequisition(row:Requisition):void { void submit(`/api/v1/backend/procurement/requisitions/${row.id}/approve`,{},()=>{},'Requisition approved.'); }
function rejectRequisition(row:Requisition):void { const reason=window.prompt('Enter rejection reason:'); if(reason?.trim()) void submit(`/api/v1/backend/procurement/requisitions/${row.id}/reject`,{reason:reason.trim()},()=>{},'Requisition rejected.'); }
function cancelRequisition(row:Requisition):void { if(window.confirm('Cancel this requisition?')) void submit(`/api/v1/backend/procurement/requisitions/${row.id}/cancel`,{},()=>{},'Requisition cancelled.'); }
function submitOrder(row:PurchaseOrder):void { void submit(`/api/v1/backend/procurement/orders/${row.id}/submit`,{},()=>{},'Purchase order submitted for approval.'); }
function approveOrder(row:PurchaseOrder):void { void submit(`/api/v1/backend/procurement/orders/${row.id}/approve`,{},()=>{},'Purchase order approved.'); }
function rejectOrder(row:PurchaseOrder):void { const reason=window.prompt('Enter rejection reason:'); if(reason?.trim()) void submit(`/api/v1/backend/procurement/orders/${row.id}/reject`,{reason:reason.trim()},()=>{},'Purchase order rejected.'); }
function cancelOrder(row:PurchaseOrder):void { if(window.confirm('Cancel this purchase order?')) void submit(`/api/v1/backend/procurement/orders/${row.id}/cancel`,{},()=>{},'Purchase order cancelled.'); }

async function openSupplierProfile(supplier:Supplier):Promise<void> {
    profileSupplier.value=null; profileLoading.value=true; error.value='';
    try { const result=await api<{supplier:SupplierProfile}>(`/api/v1/backend/procurement/suppliers/${supplier.id}`); profileSupplier.value=result.supplier; }
    catch(e) { error.value=e instanceof Error?e.message:'Unable to load supplier profile.'; }
    finally { profileLoading.value=false; }
}
async function addSupplierContact():Promise<void> {
    if(!profileSupplier.value) return;
    profileSaving.value=true; error.value='';
    try {
        await api(`/api/v1/backend/procurement/suppliers/${profileSupplier.value.id}/contacts`,{method:'POST',body:JSON.stringify({...contactForm})});
        Object.assign(contactForm,{name:'',designation:'',email:'',phone:'',is_primary:false,notes:''});
        await openSupplierProfile(profileSupplier.value);
        success.value='Supplier contact added.';
    } catch(e) { error.value=e instanceof Error?e.message:'Unable to add supplier contact.'; }
    finally { profileSaving.value=false; }
}
async function deleteSupplierContact(contact:SupplierContact):Promise<void> {
    if(!profileSupplier.value || !window.confirm(`Delete contact ${contact.name}?`)) return;
    try { await api(`/api/v1/backend/procurement/suppliers/${profileSupplier.value.id}/contacts/${contact.id}`,{method:'DELETE'}); await openSupplierProfile(profileSupplier.value); success.value='Supplier contact deleted.'; }
    catch(e) { error.value=e instanceof Error?e.message:'Unable to delete supplier contact.'; }
}
async function uploadSupplierDocument(event:Event):Promise<void> {
    const input=event.target as HTMLInputElement, file=input.files?.[0];
    if(!profileSupplier.value || !file) return;
    const form=new FormData(); form.append('file',file); form.append('category',documentCategory.value); if(documentExpiry.value) form.append('expires_at',documentExpiry.value);
    profileSaving.value=true; error.value='';
    try {
        const response=await fetch(`/api/v1/backend/procurement/suppliers/${profileSupplier.value.id}/documents`,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest','X-XSRF-TOKEN':csrf()},body:form});
        const payload=await response.json().catch(()=>({}));
        if(!response.ok) throw new Error(payload.errors?Object.values(payload.errors).flat().join(' '):payload.message||'Document upload failed.');
        await openSupplierProfile(profileSupplier.value); success.value='Supplier document uploaded.'; input.value=''; documentExpiry.value='';
    } catch(e) { error.value=e instanceof Error?e.message:'Unable to upload supplier document.'; }
    finally { profileSaving.value=false; }
}
async function deleteSupplierDocument(document:SupplierDocument):Promise<void> {
    if(!profileSupplier.value || !window.confirm(`Delete document ${document.original_name}?`)) return;
    try { await api(`/api/v1/backend/procurement/suppliers/${profileSupplier.value.id}/documents/${document.id}`,{method:'DELETE'}); await openSupplierProfile(profileSupplier.value); success.value='Supplier document deleted.'; }
    catch(e) { error.value=e instanceof Error?e.message:'Unable to delete supplier document.'; }
}
function formatBytes(bytes:number):string { if(bytes<1024) return `${bytes} B`; if(bytes<1048576) return `${(bytes/1024).toFixed(1)} KB`; return `${(bytes/1048576).toFixed(1)} MB`; }
function supplierBalance(id:number):string { return data.value?.supplier_balances.find(x=>x.supplier_id===id)?.balance??'0'; }
function itemLabel(item:POItem):string { return item.description || item.product?.name || item.variant?.product?.name || `Item #${item.id}`; }
function money(v:string|number):string { return new Intl.NumberFormat('en-BD',{style:'currency',currency:'BDT',maximumFractionDigits:2}).format(Number(v||0)); }
function closeAll():void { showSupplier.value=showOrder.value=showReceive.value=showInvoice.value=showPayment.value=showReturn.value=showRequisition.value=showRevision.value=false; }
onMounted(load);
</script>

<template>
    <Head title="Procurement & Suppliers" />
    <ErpLayout :user-name="props.userName" :user-email="props.userEmail">
        <div class="space-y-6 p-4 md:p-6">
            <div class="flex flex-wrap items-start justify-between gap-4">
                <div><p class="text-sm font-medium text-[var(--ms-primary)]">Operations / Supply Chain</p><h1 class="mt-1 text-2xl font-bold text-slate-900 dark:text-white">Procurement & Suppliers</h1><p class="mt-1 text-sm text-slate-500">Manage supplier records, purchasing, receiving and accounts payable.</p></div>
                <div class="flex flex-wrap gap-2">
                    <button class="rounded-lg border px-3 py-2 text-sm" @click="openSupplier">Add Supplier</button>
                    <button class="rounded-lg border px-3 py-2 text-sm" @click="requisitionItems=[{product_id:null,product_variant_id:null,quantity:'1'}]; showRequisition=true">New Requisition</button>
                    <button class="rounded-lg bg-[var(--ms-primary)] px-3 py-2 text-sm font-semibold text-white" @click="orderItems=[{product_id:null,product_variant_id:null,quantity:'1',unit_cost:'0.00',discount_amount:'0.00',tax_amount:'0.00',description:''}]; Object.assign(orderForm,{supplier_id:'',location_id:'',purchase_requisition_id:'',order_date:new Date().toISOString().slice(0,10),expected_at:'',notes:''}); showOrder=true">Create Purchase Order</button>
                </div>
            </div>
            <div v-if="error" class="rounded-lg border border-[var(--ms-danger)] bg-[var(--ms-danger-soft)] p-3 text-sm text-[var(--ms-danger)]">{{ error }}</div>
            <div v-if="success" class="rounded-lg border border-[var(--ms-success)] bg-[var(--ms-success-soft)] p-3 text-sm text-[var(--ms-success)]">{{ success }}</div>
            <div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
                <div class="rounded-xl border bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><p class="text-xs text-slate-500">Active suppliers</p><p class="mt-2 text-2xl font-bold">{{ data?.summary.active_suppliers??0 }}</p></div>
                <div class="rounded-xl border bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><p class="text-xs text-slate-500">Open purchase orders</p><p class="mt-2 text-2xl font-bold">{{ data?.summary.open_purchase_orders??0 }}</p></div>
                <div class="rounded-xl border bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><p class="text-xs text-slate-500">Invoices awaiting payment</p><p class="mt-2 text-2xl font-bold">{{ data?.summary.unpaid_invoices??0 }}</p></div>
                <div class="rounded-xl border bg-white p-4 dark:border-slate-700 dark:bg-slate-900"><p class="text-xs text-slate-500">Outstanding payable</p><p class="mt-2 text-2xl font-bold">{{ money(data?.summary.outstanding_payable??'0') }}</p></div>
            </div>
            <div v-if="tab==='suppliers'" class="flex justify-end"><a href="/api/v1/backend/procurement/suppliers/export" class="rounded-lg border px-3 py-2 text-sm hover:bg-slate-50 dark:border-slate-700 dark:hover:bg-slate-800">Export suppliers CSV</a></div>
            <div class="flex flex-wrap gap-2 border-b pb-2 dark:border-slate-700">
                <button v-for="item in [{id:'suppliers',label:'Suppliers'},{id:'requisitions',label:'Requisitions'},{id:'orders',label:'Purchase Orders'},{id:'receipts',label:'Goods Receipts'},{id:'invoices',label:'Supplier Invoices'},{id:'payments',label:'Payments'},{id:'returns',label:'Returns'}]" :key="item.id" class="rounded-lg px-3 py-2 text-sm" :class="tab===item.id?'bg-[var(--ms-primary)] text-white':'text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800'" @click="tab=item.id as 'suppliers'|'requisitions'|'orders'|'receipts'|'invoices'|'payments'|'returns'">{{ item.label }}</button>
            </div>
            <div v-if="loading" class="py-12 text-center text-sm text-slate-500">Loading procurement records…</div>
            <div v-else class="overflow-x-auto rounded-xl border bg-white dark:border-slate-700 dark:bg-slate-900">
                <table v-if="tab==='suppliers'" class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th class="p-3">Supplier</th><th class="p-3">Contact</th><th class="p-3">Credit terms</th><th class="p-3">Orders</th><th class="p-3">Payable balance</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><tr v-for="s in data?.suppliers??[]" :key="s.id" class="border-t dark:border-slate-800"><td class="p-3"><b>{{ s.name }}</b><p class="text-xs text-slate-500">{{ s.supplier_code }}</p></td><td class="p-3">{{ s.contact_person||'—' }}<p class="text-xs text-slate-500">{{ s.email||s.phone||'—' }}</p></td><td class="p-3">{{ s.credit_days }} days</td><td class="p-3">{{ s.purchase_orders_count??0 }}</td><td class="p-3">{{ money(supplierBalance(s.id)) }}</td><td class="p-3">{{ s.status }}</td><td class="p-3"><div class="flex gap-3"><button class="cursor-pointer text-[var(--ms-primary)] hover:underline" type="button" @click="openSupplierProfile(s)">Profile</button><button class="cursor-pointer text-[var(--ms-primary)] hover:underline" type="button" @click="editSupplier(s)">Edit</button></div></td></tr></tbody></table>
                <table v-else-if="tab==='requisitions'" class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th class="p-3">Requisition</th><th class="p-3">Location</th><th class="p-3">Required by</th><th class="p-3">Status</th><th class="p-3">Action</th></tr></thead><tbody><tr v-for="r in data?.requisitions??[]" :key="r.id" class="border-t dark:border-slate-800"><td class="p-3 font-medium">{{ r.requisition_number }}</td><td class="p-3">{{ r.location?.name??'—' }}</td><td class="p-3">{{ r.required_by??'—' }}</td><td class="p-3">{{ r.status }}</td><td class="p-3"><div class="flex flex-wrap gap-2"><button v-if="['draft','rejected'].includes(r.status)" class="text-[var(--ms-primary)]" @click="submitRequisition(r)">Submit</button><button v-if="['draft','submitted'].includes(r.status)" class="text-[var(--ms-primary)]" @click="approveRequisition(r)">Approve</button><button v-if="['draft','submitted'].includes(r.status)" class="text-rose-600" @click="rejectRequisition(r)">Reject</button><button v-if="['draft','rejected'].includes(r.status)" class="text-slate-500" @click="cancelRequisition(r)">Cancel</button></div></td></tr></tbody></table>
                <table v-else-if="tab==='orders'" class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th class="p-3">PO</th><th class="p-3">Supplier</th><th class="p-3">Location</th><th class="p-3">Total</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><tr v-for="po in data?.purchase_orders??[]" :key="po.id" class="border-t dark:border-slate-800"><td class="p-3 font-medium">{{ po.po_number }}<p class="text-xs font-normal text-slate-500">Revision {{ po.revision_no??1 }}</p></td><td class="p-3">{{ po.supplier?.name??'—' }}</td><td class="p-3">{{ po.location?.name??'—' }}</td><td class="p-3">{{ money(po.grand_total) }}</td><td class="p-3">{{ po.status }}</td><td class="p-3"><div class="flex flex-wrap gap-2"><button v-if="['draft','rejected'].includes(po.status)" class="cursor-pointer text-[var(--ms-primary)] hover:underline" @click="submitOrder(po)">Submit</button><button v-if="['draft','submitted'].includes(po.status)" class="cursor-pointer text-[var(--ms-primary)] hover:underline" @click="approveOrder(po)">Approve</button><button v-if="['draft','submitted'].includes(po.status)" class="cursor-pointer text-rose-600 hover:underline" @click="rejectOrder(po)">Reject</button><button v-if="['draft','rejected'].includes(po.status)" class="cursor-pointer text-slate-500 hover:underline" @click="cancelOrder(po)">Cancel</button><button v-if="po.status==='approved'" class="cursor-pointer text-[var(--ms-primary)] hover:underline" @click="openRevision(po)">Request revision</button><button v-if="['approved','partially_received'].includes(po.status)" class="cursor-pointer text-[var(--ms-primary)] hover:underline" @click="openReceive(po)">Receive</button><button v-if="['partially_received','received'].includes(po.status)" class="cursor-pointer text-[var(--ms-primary)] hover:underline" @click="openInvoice(po)">Add invoice</button></div><div v-if="(po.revisions??[]).length" class="mt-2 space-y-2"><details v-for="revision in po.revisions" :key="revision.id" class="rounded-lg bg-slate-50 p-2 text-xs dark:bg-slate-800"><summary class="cursor-pointer font-medium">Revision #{{ revision.revision_number }} · {{ revision.status }} · {{ revision.creator?.name??'Unknown requester' }}</summary><p class="mt-1 text-slate-500">{{ revision.reason }}</p><p v-if="revision.rejection_reason" class="mt-1 text-rose-600">Rejected: {{ revision.rejection_reason }}</p><p v-if="revision.reviewer" class="mt-1 text-slate-500">Reviewed by {{ revision.reviewer.name }}</p><div v-if="revision.status==='submitted'" class="mt-2 flex gap-3"><button class="cursor-pointer text-emerald-700 hover:underline" @click="approveRevision(revision)">Approve revision</button><button class="cursor-pointer text-rose-600 hover:underline" @click="rejectRevision(revision)">Reject revision</button></div><p v-if="revision.proposed_data?.items?.length" class="mt-1 text-slate-500">{{ revision.proposed_data.items.length }} proposed line(s)</p></details></div></td></tr></tbody></table>
                <table v-else-if="tab==='receipts'" class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th class="p-3">GRN</th><th class="p-3">Received date</th><th class="p-3">Status</th></tr></thead><tbody><tr v-for="r in data?.goods_receipts??[]" :key="r.id" class="border-t dark:border-slate-800"><td class="p-3 font-medium">{{ r.grn_number }}</td><td class="p-3">{{ r.received_date }}</td><td class="p-3">{{ r.status }}</td></tr></tbody></table>
                <table v-else-if="tab==='invoices'" class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th class="p-3">Invoice</th><th class="p-3">Supplier</th><th class="p-3">Total</th><th class="p-3">Paid</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><tr v-for="inv in data?.invoices??[]" :key="inv.id" class="border-t dark:border-slate-800"><td class="p-3 font-medium">{{ inv.invoice_number }}</td><td class="p-3">{{ inv.supplier?.name??'—' }}</td><td class="p-3">{{ money(inv.grand_total) }}</td><td class="p-3">{{ money(inv.paid_total) }}</td><td class="p-3">{{ inv.status }}</td><td class="p-3"><div class="flex gap-2"><button v-if="inv.status==='draft'" class="text-[var(--ms-primary)]" @click="postInvoice(inv)">Post</button><button v-if="['posted','partially_paid'].includes(inv.status)" class="text-[var(--ms-primary)]" @click="openPayment(inv)">Pay</button><button v-if="['posted','partially_paid','paid'].includes(inv.status)" class="text-[var(--ms-danger)]" @click="openReturn(inv)">Return goods</button></div></td></tr></tbody></table>
                <table v-else-if="tab==='payments'" class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th class="p-3">Payment</th><th class="p-3">Date</th><th class="p-3">Invoice</th><th class="p-3">Amount</th></tr></thead><tbody><tr v-for="p in data?.payments??[]" :key="p.id" class="border-t dark:border-slate-800"><td class="p-3 font-medium">{{ p.payment_number }}</td><td class="p-3">{{ p.payment_date }}</td><td class="p-3">{{ p.supplier_invoice?.invoice_number??'—' }}</td><td class="p-3">{{ money(p.amount) }}</td></tr></tbody></table>
                <table v-else class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500 dark:bg-slate-800"><tr><th class="p-3">Return</th><th class="p-3">Date</th><th class="p-3">Total</th></tr></thead><tbody><tr v-for="r in data?.returns??[]" :key="r.id" class="border-t dark:border-slate-800"><td class="p-3 font-medium">{{ r.return_number }}</td><td class="p-3">{{ r.return_date }}</td><td class="p-3">{{ money(r.total_amount) }}</td></tr></tbody></table>
                <div v-if="!loading && tab==='suppliers' && !data?.suppliers.length" class="p-8 text-center text-sm text-slate-500">No suppliers found.</div>
            </div>
            <div v-if="showSupplier||showRequisition||showOrder||showReceive||showInvoice||showPayment||showReturn||showRevision" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4" @click.self="closeAll">
                <div class="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-5 shadow-xl dark:bg-slate-900">
                    <div class="mb-4 flex items-center justify-between"><h2 class="text-lg font-semibold">{{ showSupplier?(editingSupplierId?'Edit supplier':'Add supplier'):showRequisition?'New purchase requisition':showOrder?'Create purchase order':showReceive?'Receive goods':showInvoice?'Record supplier invoice':showReturn?'Return goods to supplier':showRevision?'Revise purchase order':'Record supplier payment' }}</h2><button class="rounded-lg px-3 py-1 hover:bg-slate-100 dark:hover:bg-slate-800" @click="closeAll">✕</button></div>
                    <form v-if="showSupplier" class="grid gap-3 sm:grid-cols-2" @submit.prevent="saveSupplier"><label class="text-sm">Supplier name<input v-model="supplierForm.name" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Supplier code<input v-model="supplierForm.supplier_code" :disabled="!!editingSupplierId" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800 disabled:opacity-60"></label><label class="text-sm">Legal name<input v-model="supplierForm.legal_name" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Email<input v-model="supplierForm.email" type="email" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Phone<input v-model="supplierForm.phone" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Contact person<input v-model="supplierForm.contact_person" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Tax number<input v-model="supplierForm.tax_number" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Credit days<input v-model="supplierForm.credit_days" type="number" min="0" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Payment terms<input v-model="supplierForm.payment_terms" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">City<input v-model="supplierForm.city" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Country<input v-model="supplierForm.country" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label v-if="editingSupplierId" class="text-sm">Status<select v-model="supplierForm.status" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="active">Active</option><option value="inactive">Inactive</option><option value="blocked">Blocked</option></select></label><label class="text-sm sm:col-span-2">Address<textarea v-model="supplierForm.address" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></textarea></label><label class="text-sm sm:col-span-2">Notes<textarea v-model="supplierForm.notes" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></textarea></label><div class="sm:col-span-2 flex justify-end"><button :disabled="saving" class="rounded-lg bg-[var(--ms-primary)] px-4 py-2 text-white disabled:opacity-50">{{ editingSupplierId?'Update supplier':'Save supplier' }}</button></div></form>
                    <form v-else-if="showRequisition" class="grid gap-3" @submit.prevent="saveRequisition"><div class="grid gap-3 sm:grid-cols-2"><label class="text-sm">Location<select v-model="requisitionForm.location_id" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="">Select</option><option v-for="l in data?.locations.filter(x=>x.access_level==='manage')??[]" :key="l.id" :value="String(l.id)">{{ l.name }}</option></select></label><label class="text-sm">Required by<input v-model="requisitionForm.required_by" type="date" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm sm:col-span-2">Purpose<input v-model="requisitionForm.purpose" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label></div><div class="flex items-center justify-between"><h3 class="font-semibold">Requested items</h3><button type="button" class="rounded-lg border px-3 py-1.5 text-sm" @click="addRequisitionItem">Add line</button></div><div v-for="(item,index) in requisitionItems" :key="index" class="grid gap-2 rounded-xl border p-3 dark:border-slate-700 sm:grid-cols-2"><div class="flex items-center justify-between sm:col-span-2"><span class="text-xs font-semibold text-slate-500">Line {{ index+1 }}</span><button type="button" class="text-xs text-rose-600 disabled:opacity-40" :disabled="requisitionItems.length===1" @click="removeRequisitionItem(index)">Remove</button></div><label class="text-sm">Product<select v-model="item.product_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800" @change="item.product_variant_id=null"><option :value="null">Choose product</option><option v-for="product in data?.products??[]" :key="product.id" :value="product.id">{{ product.name }} ({{ product.sku }})</option></select></label><label class="text-sm">Variant<select v-model="item.product_variant_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800" @change="item.product_id=null"><option :value="null">Choose variant</option><option v-for="variant in data?.variants??[]" :key="variant.id" :value="variant.id">{{ variant.product?.name }} — {{ variant.name }} ({{ variant.sku }})</option></select></label><label class="text-sm">Quantity<input v-model="item.quantity" type="number" min="0.0001" step="0.0001" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label></div><div class="flex justify-end"><button :disabled="saving" class="rounded-lg bg-[var(--ms-primary)] px-4 py-2 text-white disabled:opacity-50">Create requisition</button></div></form>
                    <form v-else-if="showOrder" class="grid gap-3" @submit.prevent="saveOrder"><div class="grid gap-3 sm:grid-cols-2"><label class="text-sm">Supplier<select v-model="orderForm.supplier_id" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="">Select</option><option v-for="supplier in data?.suppliers.filter(x=>x.status==='active')??[]" :key="supplier.id" :value="String(supplier.id)">{{ supplier.name }}</option></select></label><label class="text-sm">Location<select v-model="orderForm.location_id" required :disabled="!!orderForm.purchase_requisition_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800 disabled:opacity-60"><option value="">Select</option><option v-for="location in data?.locations.filter(x=>x.access_level==='manage')??[]" :key="location.id" :value="String(location.id)">{{ location.name }}</option></select></label><label class="text-sm sm:col-span-2">Approved requisition<select v-model="orderForm.purchase_requisition_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800" @change="loadRequisitionLines"><option value="">Direct purchase (no requisition)</option><option v-for="req in data?.requisitions.filter(x=>x.status==='approved')??[]" :key="req.id" :value="String(req.id)">{{ req.requisition_number }} — {{ req.location?.name }}</option></select><span class="text-xs text-slate-500">Selecting an approved requisition loads every requested line and quantity. Enter unit cost for each line; the backend verifies exact coverage and prevents duplicate conversion.</span></label><label class="text-sm">Order date<input v-model="orderForm.order_date" type="date" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Expected date<input v-model="orderForm.expected_at" type="date" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm sm:col-span-2">Notes<textarea v-model="orderForm.notes" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></textarea></label></div><div class="flex items-center justify-between"><h3 class="font-semibold">Purchase order lines</h3><button type="button" class="rounded-lg border px-3 py-1.5 text-sm" @click="addOrderItem" :disabled="!!orderForm.purchase_requisition_id">Add line</button></div><div v-for="(item,index) in orderItems" :key="index" class="grid gap-2 rounded-xl border p-3 dark:border-slate-700 sm:grid-cols-2"><div class="flex items-center justify-between sm:col-span-2"><span class="text-xs font-semibold text-slate-500">Line {{ index+1 }}</span><button type="button" class="text-xs text-rose-600 disabled:opacity-40" :disabled="orderItems.length===1 || !!orderForm.purchase_requisition_id" @click="removeOrderItem(index)">Remove</button></div><label class="text-sm">Product<select v-model="item.product_id" :disabled="!!orderForm.purchase_requisition_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800" @change="item.product_variant_id=null"><option :value="null">Choose product</option><option v-for="product in data?.products??[]" :key="product.id" :value="product.id">{{ product.name }} ({{ product.sku }})</option></select></label><label class="text-sm">Variant<select v-model="item.product_variant_id" :disabled="!!orderForm.purchase_requisition_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800" @change="item.product_id=null"><option :value="null">Choose variant</option><option v-for="variant in data?.variants??[]" :key="variant.id" :value="variant.id">{{ variant.product?.name }} — {{ variant.name }} ({{ variant.sku }})</option></select></label><label class="text-sm">Quantity<input v-model="item.quantity" type="number" min="0.0001" step="0.0001" required :readonly="!!orderForm.purchase_requisition_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800 read-only:opacity-70"></label><label class="text-sm">Unit cost<input v-model="item.unit_cost" type="number" min="0.01" step="0.01" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Discount<input v-model="item.discount_amount" type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Tax<input v-model="item.tax_amount" type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm sm:col-span-2">Description<input v-model="item.description" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label></div><div class="flex justify-end"><button :disabled="saving" class="rounded-lg bg-[var(--ms-primary)] px-4 py-2 text-white disabled:opacity-50">Save draft PO</button></div></form>
                    <form v-else-if="showRevision" class="grid gap-4" @submit.prevent="saveRevision">
                        <div class="rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm text-amber-900 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-200">This submits a proposed revision. The approved purchase order remains unchanged until a different authorized user approves it. Revision is blocked once goods receiving or supplier invoicing has started.</div>
                        <label class="text-sm">Reason for revision<textarea v-model="revisionForm.reason" required minlength="5" maxlength="2000" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></textarea></label>
                        <div class="grid gap-3 sm:grid-cols-2"><label class="text-sm">Order date<input v-model="revisionForm.order_date" type="date" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Expected date<input v-model="revisionForm.expected_at" type="date" :min="revisionForm.order_date" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label></div>
                        <label class="text-sm">Notes<textarea v-model="revisionForm.notes" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></textarea></label>
                        <div class="flex items-center justify-between"><h3 class="font-semibold">Proposed purchase order lines</h3><button type="button" class="rounded-lg border px-3 py-1.5 text-sm" @click="addRevisionItem">Add line</button></div>
                        <div v-for="(item,index) in revisionItems" :key="index" class="rounded-xl border p-3 dark:border-slate-700">
                            <div class="mb-2 flex items-center justify-between"><span class="text-xs font-semibold text-slate-500">Line {{ index+1 }}</span><button type="button" class="text-xs text-rose-600 disabled:opacity-40" :disabled="revisionItems.length===1" @click="removeRevisionItem(index)">Remove</button></div>
                            <div class="grid gap-2 sm:grid-cols-2">
                                <label class="text-sm">Product<select v-model="item.product_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800" @change="item.product_variant_id=null"><option :value="null">Choose product</option><option v-for="product in data?.products??[]" :key="product.id" :value="product.id">{{ product.name }} ({{ product.sku }})</option></select></label>
                                <label class="text-sm">Variant<select v-model="item.product_variant_id" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800" @change="item.product_id=null"><option :value="null">Choose variant</option><option v-for="variant in data?.variants??[]" :key="variant.id" :value="variant.id">{{ variant.product?.name }} — {{ variant.name }} ({{ variant.sku }})</option></select></label>
                                <label class="text-sm">Quantity<input v-model="item.quantity" required inputmode="decimal" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label>
                                <label class="text-sm">Unit cost<input v-model="item.unit_cost" required inputmode="decimal" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label>
                                <label class="text-sm">Discount<input v-model="item.discount_amount" inputmode="decimal" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label>
                                <label class="text-sm">Tax<input v-model="item.tax_amount" inputmode="decimal" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label>
                                <label class="text-sm sm:col-span-2">Description<input v-model="item.description" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label>
                            </div>
                        </div>
                        <div class="flex justify-end"><button :disabled="saving" class="rounded-lg bg-[var(--ms-primary)] px-4 py-2 text-white disabled:opacity-50">Submit revision for approval</button></div>
                    </form>
                    <form v-else-if="showReceive" class="grid gap-3 sm:grid-cols-2" @submit.prevent="saveReceipt"><label class="text-sm sm:col-span-2">Purchase order item<select v-model="receiveForm.purchase_order_item_id" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="">Select item</option><option v-for="i in selectedOrder?.items??[]" :key="i.id" :value="String(i.id)">{{ itemLabel(i) }} — ordered {{ i.quantity }}, physically received {{ i.received_quantity }}, accepted {{ i.accepted_quantity }}</option></select></label><label class="text-sm">Received quantity<input v-model="receiveForm.received_quantity" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Accepted quantity<input v-model="receiveForm.accepted_quantity" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Rejected quantity<input v-model="receiveForm.rejected_quantity" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Delivery note<input v-model="receiveForm.delivery_note" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm sm:col-span-2">Rejection reason<input v-model="receiveForm.rejection_reason" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><div class="sm:col-span-2 flex justify-end"><button class="rounded-lg bg-[var(--ms-primary)] px-4 py-2 text-white">Post GRN</button></div></form>
                    <form v-else-if="showInvoice" class="grid gap-3 sm:grid-cols-2" @submit.prevent="saveInvoice"><label class="text-sm">Supplier invoice number<input v-model="invoiceForm.invoice_number" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Invoice date<input v-model="invoiceForm.invoice_date" type="date" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Due date<input v-model="invoiceForm.due_date" type="date" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm sm:col-span-2">Received PO item<select v-model="invoiceForm.purchase_order_item_id" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="">Select accepted item</option><option v-for="i in data?.purchase_orders.find(x=>String(x.id)===invoiceForm.order_id)?.items??[]" :key="i.id" :value="String(i.id)" :disabled="invoiceRemaining(data!.purchase_orders.find(x=>String(x.id)===invoiceForm.order_id)!,i)<=0">{{ itemLabel(i) }} — remaining to invoice {{ invoiceRemaining(data!.purchase_orders.find(x=>String(x.id)===invoiceForm.order_id)!,i) }}</option></select></label><label class="text-sm">Invoice quantity<input v-model="invoiceForm.quantity" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Unit cost (must match PO)<input v-model="invoiceForm.unit_cost" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Tax<input v-model="invoiceForm.tax_total" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Discount<input v-model="invoiceForm.discount_total" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><div class="sm:col-span-2 flex justify-end"><button class="rounded-lg bg-[var(--ms-primary)] px-4 py-2 text-white">Save draft invoice</button></div></form>
                    <form v-else-if="showReturn" class="grid gap-3 sm:grid-cols-2" @submit.prevent="saveReturn"><label class="text-sm sm:col-span-2">Purchase order item<select v-model="returnForm.purchase_order_item_id" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="">Select item</option><option v-for="line in selectedReturnInvoice?.items??[]" :key="line.purchase_order_item_id" :value="String(line.purchase_order_item_id)" :disabled="returnRemaining(selectedReturnInvoice!,line.purchase_order_item_id)<=0">{{ itemLabel(selectedReturnOrder?.items.find(i=>i.id===line.purchase_order_item_id)??({id:line.purchase_order_item_id,description:null,product:null,variant:null} as POItem)) }} — returnable {{ returnRemaining(selectedReturnInvoice!,line.purchase_order_item_id) }}</option></select></label><label class="text-sm">Return quantity<input v-model="returnForm.quantity" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Return date<input v-model="returnForm.return_date" type="date" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm sm:col-span-2">Reason<textarea v-model="returnForm.reason" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></textarea></label><div class="sm:col-span-2 flex justify-end"><button class="rounded-lg bg-rose-600 px-4 py-2 text-white">Post supplier return</button></div></form>
                    <form v-else class="grid gap-3 sm:grid-cols-2" @submit.prevent="savePayment"><label class="text-sm">Payment date<input v-model="paymentForm.payment_date" type="date" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Amount<input v-model="paymentForm.amount" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><label class="text-sm">Payment method<select v-model="paymentForm.payment_method" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_banking">Mobile banking</option><option value="card">Card</option><option value="other">Other</option></select></label><label class="text-sm">Cash/bank account<select v-model="paymentForm.cash_account_id" required class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"><option v-for="a in data?.cash_accounts??[]" :key="a.id" :value="String(a.id)">{{ a.code }} — {{ a.name }}</option></select></label><label class="text-sm sm:col-span-2">Reference<input v-model="paymentForm.reference" class="mt-1 w-full rounded-lg border p-2 dark:bg-slate-800"></label><div class="sm:col-span-2 flex justify-end"><button class="rounded-lg bg-[var(--ms-primary)] px-4 py-2 text-white">Post payment</button></div></form>
                </div>
            </div>
            <div v-if="profileLoading || profileSupplier" class="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/60 p-4" @click.self="profileSupplier=null">
                <div class="max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-2xl bg-white p-5 shadow-2xl dark:bg-slate-900">
                    <div class="mb-5 flex items-start justify-between gap-3"><div><h2 class="text-xl font-semibold">Supplier Profile</h2><p v-if="profileSupplier" class="text-sm text-slate-500">{{ profileSupplier.name }} · {{ profileSupplier.supplier_code }}</p></div><button type="button" class="rounded-lg px-3 py-1 hover:bg-slate-100 dark:hover:bg-slate-800" @click="profileSupplier=null">✕</button></div>
                    <div v-if="profileLoading" class="py-10 text-center text-sm text-slate-500">Loading supplier profile…</div>
                    <div v-else-if="profileSupplier" class="space-y-6">
                        <div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div class="rounded-xl border p-3 dark:border-slate-700"><p class="text-xs text-slate-500">Status</p><p class="mt-1 font-semibold capitalize">{{ profileSupplier.status }}</p></div><div class="rounded-xl border p-3 dark:border-slate-700"><p class="text-xs text-slate-500">Purchase orders</p><p class="mt-1 font-semibold">{{ profileSupplier.purchase_orders_count }}</p></div><div class="rounded-xl border p-3 dark:border-slate-700"><p class="text-xs text-slate-500">Invoices</p><p class="mt-1 font-semibold">{{ profileSupplier.invoices_count }}</p></div><div class="rounded-xl border p-3 dark:border-slate-700"><p class="text-xs text-slate-500">Credit terms</p><p class="mt-1 font-semibold">{{ profileSupplier.credit_days }} days</p></div></div>
                        <section class="space-y-3"><h3 class="font-semibold">Purchase history</h3><div v-if="!profileSupplier.purchase_orders.length" class="rounded-xl border p-4 text-sm text-slate-500 dark:border-slate-700">No purchase orders are visible for your assigned locations.</div><div v-else class="overflow-x-auto rounded-xl border dark:border-slate-700"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500 dark:bg-slate-800"><tr><th class="p-3">PO number</th><th class="p-3">Date</th><th class="p-3">Location</th><th class="p-3">Total</th><th class="p-3">Status</th></tr></thead><tbody><tr v-for="po in profileSupplier.purchase_orders" :key="po.id" class="border-t dark:border-slate-700"><td class="p-3 font-medium">{{ po.po_number }}<p class="text-xs font-normal text-slate-500">Revision {{ po.revision_no??1 }}</p></td><td class="p-3">{{ po.order_date||'—' }}</td><td class="p-3">{{ po.location||'—' }}</td><td class="p-3">{{ money(po.grand_total) }}</td><td class="p-3 capitalize">{{ po.status.replaceAll('_',' ') }}</td></tr></tbody></table></div></section>
                        <section class="space-y-2"><h3 class="font-semibold">Recent activity</h3><div v-if="!profileSupplier.activity.length" class="rounded-xl border p-4 text-sm text-slate-500 dark:border-slate-700">No supplier activity recorded yet.</div><div v-for="entry in profileSupplier.activity" :key="entry.id" class="flex items-start justify-between gap-3 rounded-xl border p-3 text-sm dark:border-slate-700"><div><p class="font-medium">{{ entry.description }}</p><p class="text-xs capitalize text-slate-500">{{ entry.action }}</p></div><time class="shrink-0 text-xs text-slate-500">{{ new Date(entry.created_at).toLocaleString() }}</time></div></section>
                        <section class="space-y-2"><h3 class="font-semibold">Business information</h3><div class="grid gap-3 rounded-xl border p-4 text-sm dark:border-slate-700 sm:grid-cols-2"><p><span class="text-slate-500">Legal name:</span> {{ profileSupplier.legal_name||'—' }}</p><p><span class="text-slate-500">Tax number:</span> {{ profileSupplier.tax_number||'—' }}</p><p><span class="text-slate-500">Email:</span> {{ profileSupplier.email||'—' }}</p><p><span class="text-slate-500">Phone:</span> {{ profileSupplier.phone||'—' }}</p><p><span class="text-slate-500">Payment terms:</span> {{ profileSupplier.payment_terms||'—' }}</p><p><span class="text-slate-500">Address:</span> {{ [profileSupplier.address,profileSupplier.city,profileSupplier.country].filter(Boolean).join(', ')||'—' }}</p></div></section>
                        <section class="space-y-3"><div class="flex items-center justify-between"><h3 class="font-semibold">Contacts</h3><span class="text-xs text-slate-500">{{ profileSupplier.contacts.length }} contact(s)</span></div><div v-if="!profileSupplier.contacts.length" class="rounded-xl border p-4 text-sm text-slate-500 dark:border-slate-700">No additional contacts recorded.</div><div v-for="contact in profileSupplier.contacts" :key="contact.id" class="flex items-center justify-between gap-3 rounded-xl border p-3 dark:border-slate-700"><div class="min-w-0"><p class="font-medium">{{ contact.name }} <span v-if="contact.is_primary" class="ml-1 rounded bg-emerald-100 px-2 py-0.5 text-xs text-emerald-800">Primary</span></p><p class="text-xs text-slate-500">{{ contact.designation||'Contact' }} · {{ contact.email||contact.phone||'No contact details' }}</p></div><button type="button" class="text-sm text-rose-600 hover:underline" @click="deleteSupplierContact(contact)">Delete</button></div>
                            <form class="grid gap-2 rounded-xl border p-3 dark:border-slate-700 sm:grid-cols-2" @submit.prevent="addSupplierContact"><input v-model="contactForm.name" required placeholder="Contact name" class="rounded-lg border p-2 text-sm dark:bg-slate-800"><input v-model="contactForm.designation" placeholder="Designation" class="rounded-lg border p-2 text-sm dark:bg-slate-800"><input v-model="contactForm.email" type="email" placeholder="Email" class="rounded-lg border p-2 text-sm dark:bg-slate-800"><input v-model="contactForm.phone" placeholder="Phone" class="rounded-lg border p-2 text-sm dark:bg-slate-800"><label class="flex items-center gap-2 text-sm sm:col-span-2"><input v-model="contactForm.is_primary" type="checkbox"> Set as primary contact</label><div class="sm:col-span-2"><button :disabled="profileSaving" class="rounded-lg bg-[var(--ms-primary)] px-3 py-2 text-sm text-white disabled:opacity-50">Add contact</button></div></form>
                        </section>
                        <section class="space-y-3"><h3 class="font-semibold">Supplier documents</h3><div v-if="!profileSupplier.documents.length" class="rounded-xl border p-4 text-sm text-slate-500 dark:border-slate-700">No supplier documents uploaded.</div><div v-for="doc in profileSupplier.documents" :key="doc.id" class="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3 dark:border-slate-700"><div class="min-w-0"><p class="truncate font-medium">{{ doc.original_name }}</p><p class="text-xs text-slate-500">{{ doc.category.replaceAll('_',' ') }} · {{ formatBytes(doc.size) }} · {{ doc.expires_at?`Expires ${doc.expires_at}`:'No expiry date' }}</p></div><div class="flex gap-3 text-sm"><a class="text-[var(--ms-primary)] hover:underline" :href="`/api/v1/backend/procurement/suppliers/${profileSupplier.id}/documents/${doc.id}/download`">Download</a><button type="button" class="text-rose-600 hover:underline" @click="deleteSupplierDocument(doc)">Delete</button></div></div>
                            <div class="grid gap-2 rounded-xl border p-3 dark:border-slate-700 sm:grid-cols-3"><select v-model="documentCategory" class="rounded-lg border p-2 text-sm dark:bg-slate-800"><option value="other">Other</option><option value="trade_license">Trade license</option><option value="tax_certificate">Tax certificate</option><option value="bank_document">Bank document</option><option value="agreement">Agreement</option><option value="identity">Identity</option></select><input v-model="documentExpiry" type="date" class="rounded-lg border p-2 text-sm dark:bg-slate-800"><input type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" :disabled="profileSaving" class="text-sm" @change="uploadSupplierDocument"></div><p class="text-xs text-slate-500">PDF, JPG, PNG or WebP · maximum 10 MB. Documents are stored privately and require backend permission to download.</p>
                        </section>
                    </div>
                </div>
            </div>
        </div>
    </ErpLayout>
</template>
